// DeviceStorage is a persistent storage for MFA devices.
type DeviceStorage interface {
	UpsertMFADevice(ctx context.Context, key string, d *types.MFADevice) error
}

// NewDevice creates a U2F MFADevice object from a completed U2F registration.
//
// This function is not in lib/services due to an import cycle (lib/services
// depends on lib/auth/u2f).
func NewDevice(name string, reg *Registration, addedAt time.Time) (*types.MFADevice, error) {
	d := types.NewMFADevice(name, addedAt)
	pubKey, err := x509.MarshalPKIXPublicKey(&reg.PubKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	d.Device = &types.MFADevice_U2F{U2F: &types.U2FDevice{
		KeyHandle: reg.KeyHandle,
		PubKey:    pubKey,
	}}
	if err := d.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}
	if err := ValidateDevice(d.GetU2F()); err != nil {
		return nil, trace.Wrap(err)
	}
	return d, nil
}

// ValidateMFADevice validates a U2F MFA device.
//
// This function is not in lib/services due to an import cycle (lib/services
// depends on lib/auth/u2f).
func ValidateDevice(d *types.U2FDevice) error {
	if len(d.KeyHandle) == 0 {
		return trace.BadParameter("U2FDevice missing KeyHandle field")
	}
	if len(d.PubKey) == 0 {
		return trace.BadParameter("U2FDevice missing PubKey field")
	}
	if _, err := decodeDevicePubKey(d); err != nil {
		return trace.BadParameter("U2FDevice PubKey is invalid: %v", err)
	}
	return nil
}

// DeviceToRegistration decodes the U2F registration data and builds the
// expected registration object.
func DeviceToRegistration(d *types.U2FDevice) (*Registration, error) {
	pubKey, err := decodeDevicePubKey(d)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &u2f.Registration{
		KeyHandle: d.KeyHandle,
		PubKey:    *pubKey,
	}, nil
}

func decodeDevicePubKey(d *types.U2FDevice) (*ecdsa.PublicKey, error) {
	pubKeyI, err := x509.ParsePKIXPublicKey(d.PubKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	pubKey, ok := pubKeyI.(*ecdsa.PublicKey)
	if !ok {
		return nil, trace.BadParameter("expected *ecdsa.PublicKey, got %T", pubKeyI)
	}
	return pubKey, nil
}

// pollLocalDevices calls fn against all local U2F devices until one succeeds
// (fn returns nil) or until the context is cancelled.
func pollLocalDevices(ctx context.Context, fn func(t *u2ftoken.Token) error) error {
	tick := time.NewTicker(200 * time.Millisecond)
	defer tick.Stop()
	for {
		err := foreachLocalDevice(fn)
		if err == nil {
			return nil
		}
		// Don't spam the logs while we're waiting for a key to be plugged
		// in or tapped.
		if err != errAuthNoKeyOrUserPresence {
			logrus.WithError(err).Debugf("Error polling U2F devices for registration")
		}

		select {
		case <-ctx.Done():
			return trace.Wrap(ctx.Err())
		case <-tick.C:
		}
	}
}

// foreachLocalDevice runs fn against each currently available U2F device. It
// stops when fn returns nil or when finished iterating against the available
// devices.
//
// You most likely want to call pollLocalDevices instead.
func foreachLocalDevice(fn func(t *u2ftoken.Token) error) error {
	// Note: we fetch and open all devices on every polling iteration on
	// purpose. This will handle the device that a user inserts after the
	// polling has started.
	devices, err := u2fhid.Devices()
	if err != nil {
		return trace.Wrap(err)
	}
	var errs []error
	for _, d := range devices {
		dev, err := u2fhid.Open(d)
		if err != nil {
			errs = append(errs, trace.Wrap(err))
			continue
		}
		// There are usually 1-2 devices plugged in, so deferring closing all
		// of them until the end of function is not too wasteful.
		defer dev.Close()

		t := u2ftoken.NewToken(dev)
		// fn is usually t.Authenticate or t.Register. Both methods are
		// non-blocking - the U2F device returns u2ftoken.ErrPresenceRequired
		// immediately, unless the user has recently tapped the device.
		if err := fn(t); err == u2ftoken.ErrPresenceRequired || err == errAuthNoKeyOrUserPresence {
			continue
		} else if err != nil {
			errs = append(errs, trace.Wrap(err))
			continue
		}
		return nil
	}

	if len(errs) > 0 {
		return trace.NewAggregate(errs...)
	}
	return errAuthNoKeyOrUserPresence
}

	if status.IsLocked && status.LockExpires.After(a.clock.Now().UTC()) {
		return trace.AccessDenied("%v exceeds %v failed login attempts, locked until %v",
			user.GetName(), defaults.MaxLoginAttempts, utils.HumanTimeFormat(status.LockExpires))
	}
	fnErr := authenticateFn()
	if fnErr == nil {
		// upon successful login, reset the failed attempt counter
		err = a.DeleteUserLoginAttempts(username)
		if !trace.IsNotFound(err) {
			return trace.Wrap(err)
		}

		return nil
	}
	// do not lock user in case if DB is flaky or down
	if trace.IsConnectionProblem(err) {
		return trace.Wrap(fnErr)
	}
	// log failed attempt and possibly lock user
	attempt := services.LoginAttempt{Time: a.clock.Now().UTC(), Success: false}
	err = a.AddUserLoginAttempt(username, attempt, defaults.AttemptTTL)
	if err != nil {
		log.Error(trace.DebugReport(err))
		return trace.Wrap(fnErr)
	}
	loginAttempts, err := a.Identity.GetUserLoginAttempts(username)
	if err != nil {
		log.Error(trace.DebugReport(err))
		return trace.Wrap(fnErr)
	}
	if !services.LastFailed(defaults.MaxLoginAttempts, loginAttempts) {
		log.Debugf("%v user has less than %v failed login attempts", username, defaults.MaxLoginAttempts)
		return trace.Wrap(fnErr)
	}
	lockUntil := a.clock.Now().UTC().Add(defaults.AccountLockInterval)
	message := fmt.Sprintf("%v exceeds %v failed login attempts, locked until %v",
		username, defaults.MaxLoginAttempts, utils.HumanTimeFormat(status.LockExpires))
	log.Debug(message)
	user.SetLocked(lockUntil, "user has exceeded maximum failed login attempts")
	err = a.Identity.UpsertUser(user)
	if err != nil {
		log.Error(trace.DebugReport(err))
		return trace.Wrap(fnErr)
	}
	return trace.AccessDenied(message)
}

// PreAuthenticatedSignIn is for 2-way authentication methods like U2F where the password is
// already checked before issuing the second factor challenge
func (a *Server) PreAuthenticatedSignIn(user string, identity tlsca.Identity) (services.WebSession, error) {
	roles, traits, err := services.ExtractFromIdentity(a, identity)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	sess, err := a.NewWebSession(types.NewWebSessionRequest{
		User:   user,
		Roles:  roles,
		Traits: traits,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if err := a.upsertWebSession(context.TODO(), user, sess); err != nil {
		return nil, trace.Wrap(err)
	}
	return sess.WithoutSecrets(), nil
}

func (a *Server) U2FSignRequest(user string, password []byte) (*u2f.AuthenticateChallenge, error) {
	ctx := context.TODO()
	cap, err := a.GetAuthPreference()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	u2fConfig, err := cap.GetU2F()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	err = a.WithUserLock(user, func() error {
		return a.CheckPasswordWOToken(user, password)
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// TODO(awly): mfa: support challenge with multiple devices.
	devs, err := a.GetMFADevices(ctx, user)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	for _, dev := range devs {
		if dev.GetU2F() == nil {
			continue
		}
		return u2f.AuthenticateInit(ctx, u2f.AuthenticateInitParams{
			Dev:        dev,
			AppConfig:  *u2fConfig,
			StorageKey: user,
			Storage:    a.Identity,
		})
	}
	return nil, trace.NotFound("no U2F devices found for user %q", user)
}

func (a *Server) CheckU2FSignResponse(ctx context.Context, user string, response *u2f.AuthenticateChallengeResponse) error {
	// before trying to register a user, see U2F is actually setup on the backend
	cap, err := a.GetAuthPreference()
	if err != nil {
		return trace.Wrap(err)
	}
	_, err = cap.GetU2F()
	if err != nil {
		return trace.Wrap(err)
	}

	return a.checkU2F(ctx, user, *response, a.Identity)
}

// ExtendWebSession creates a new web session for a user based on a valid previous session.
// Additional roles are appended to initial roles if there is an approved access request.
// The new session expiration time will not exceed the expiration time of the old session.
func (a *Server) ExtendWebSession(user, prevSessionID, accessRequestID string, identity tlsca.Identity) (services.WebSession, error) {
	prevSession, err := a.GetWebSession(context.TODO(), types.GetWebSessionRequest{
		User:      user,
		SessionID: prevSessionID,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// consider absolute expiry time that may be set for this session
	// by some external identity serivce, so we can not renew this session
	// any more without extra logic for renewal with external OIDC provider
	expiresAt := prevSession.GetExpiryTime()
	if !expiresAt.IsZero() && expiresAt.Before(a.clock.Now().UTC()) {
		return nil, trace.NotFound("web session has expired")
	}

	roles, traits, err := services.ExtractFromIdentity(a, identity)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if accessRequestID != "" {
		newRoles, requestExpiry, err := a.getRolesAndExpiryFromAccessRequest(user, accessRequestID)
		if err != nil {
			return nil, trace.Wrap(err)
		}

	mode := clusterConfig.GetSessionRecording()
	// In sync mode, auth server forwards session control to the event log
	// in addition to sending them and data events to the record storage.
	if services.IsRecordSync(mode) {
		return events.NewTeeStreamer(a.streamer, a.emitter), nil
	}
	// In async mode, clients submit session control events
	// during the session in addition to writing a local
	// session recording to be uploaded at the end of the session,
	// so forwarding events here will result in duplicate events.
	return a.streamer, nil
}

